def samples_within_budget(budget: float, cost_per_sample: float) -> int:
    """How many whole samples the budget buys at the given per-sample cost."""
    return int(budget // cost_per_sample)

print(samples_within_budget(14.0, 1.0))

def samples_within_budget(budget: float, cost_per_sample: float) -> int:
    return int(budget // cost_per_sample)

def compute_matched_samples(budget: float, small_cost: float, large_cost: float) -> tuple:
    """(samples the small model gets, samples the large model gets) for the same budget."""
    small_samples = samples_within_budget(budget, small_cost)
    large_samples = samples_within_budget(budget, large_cost)
    return (small_samples, large_samples)

print(compute_matched_samples(14.0, 1.0, 14.0))
